scwin.grid1_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
    //				return false;
    return true;
}
scwin.grid2_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
}
scwin.selectbox1_onviewchange = function(info) {
    var data = eval("scwin.data" + info.newValue);
    dataList1.setData(data.slice(0));
}
scwin.trigger1_onclick = function() {
    var data = eval("scwin.data" + selectbox1.getValue());
    dataList1.setData(data.slice(0));
}
scwin.grid1_groupbyFilterBoxFormatter = function(f) {
    console.log(JSON.stringify(f));
}
scwin.grid1_groupbyFilterBoxFormatter = function(data) {
    console.log(data);
    var label = "";
    var labelArr = [];
    for (var i = 0; i < data.length; i++) {
        var s_label = "";
        var obj = data[i];
        var header = obj.header;
        var filter = obj.filter;
        debugger;
        for (var j = 0; j < filter.length; j++) {
            if (filter[j].gate)
                s_label = s_label + " " + filter[j].gate + " ";
            var values = filter[j].values;
            if (values.join)
                values = "[" + values.join(" ,") + "]";
            s_label = s_label + filter[j].operator + " " + values;
        }
        s_label = "(" + header + " " + s_label + ")";
        labelArr.push(s_label);
    }
    label = labelArr.join(" & ");
    console.log('label:' + label);
    return label;
};
scwin.grid1_oncellclick = function(row, col) {
    var realRow = this.getRealRowIndex(row);
    log = "row:: " + row + " col::" + col
    console.log("row:: " + row + " col::" + col + " realRow::" + realRow);
    console.log("getCellData ::" + dataList1.getCellData(row, "col3"));
    log1 = "getCellData ::" + dataList1.getCellData(row, "col3");
    grid1.setCellBackgroundColor(row, col, "yellow");
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate = function() {
	scwin.simulateWrapper('#grid1_header3', 'drag-n-drop', {
		dx: 0,
		dy: -50
	});
}
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? "#" +
        ("0" + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[3], 10).toString(16)).slice(-2) : '';
}
scwin._checkRgb = function(id, hexa) {
    var rgb = WebSquare.wUnit.getJq("#" + id).css("background-color");
    if (rgb.indexOf("rgb") != -1) {
        return rgb == "rgb(255, 255, 0)";
    }
    return rgb == hexa;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == '분류2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_cell_3_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log != ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log1 != ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_cell_4_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb('grid1_cell_3_1', 'yellow')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
